import settings from "../config/settings.json" with { type: "json" };

// Split totalCents between payers in proportion to their weights (SPEC.md).
export function settle(totalCents, weights) {
  if (!Number.isInteger(totalCents)) throw new TypeError(`amounts are integer ${settings.currency} cents`);
  const sum = weights.reduce((a, b) => a + b, 0);
  if (sum <= 0) throw new RangeError("weights must sum to a positive number");
  const shares = weights.map((w) => Math.floor((totalCents * w) / sum));
  let remainder = totalCents - shares.reduce((a, b) => a + b, 0);
  // Hand remainder cents out one at a time, in payer order, starting with the first payer (SPEC.md rule 3).
  for (let i = 0; remainder > 0; i = (i + 1) % shares.length, remainder--) shares[i] += 1;
  return shares;
}

args.command:
node -e "
import('./src/settle.js').then(({settle})=>{
  console.log(settle(10,[1,1,1])); // remainder one at a time
  console.log(settle(7,[3,1]));    // floor + remainder
  console.log(settle(5,[2,3,5]));  // sum check
});"

